'use strict';
// Número completo e identidade do provedor. Nunca aproxima pelo nome ou pelos últimos dígitos.
const queues=new WeakMap();
function phone(value,{international=false}={}){const raw=String(value||'').trim(),digits=raw.replace(/\D/g,'').replace(/^00/,'');if(!digits||/[A-Za-z@]/.test(raw))return '';const n=international||raw.startsWith('+')||raw.startsWith('00')?digits:[10,11].includes(digits.length)?'55'+digits:digits;return /^\d{10,15}$/.test(n)?n:''}
function storedPhone(value){const n=phone(value);return n&&!n.startsWith('55')&&n.length<=11?'+'+n:n}
function direct(value){const m=/^(\d+)(?::\d+)?@(s\.whatsapp\.net|c\.us)$/i.exec(String(value||''));return m?phone(m[1],{international:true}):''}
function jid(value){return String(value||'').trim().toLowerCase().replace(/:\d+(?=@)/,'').replace(/@c\.us$/,'@s.whatsapp.net')}
function expression(column){const raw=`replace(replace(replace(replace(replace(replace(COALESCE(${column},''),'(',''),')',''),'-',''),' ',''),'+',''),'.','')`,clean=`(CASE WHEN substr(${raw},1,2)='00' THEN substr(${raw},3) ELSE ${raw} END)`;return `(CASE WHEN trim(COALESCE(${column},'')) LIKE '+%' OR trim(COALESCE(${column},'')) LIKE '00%' THEN ${clean} WHEN length(${clean}) IN(10,11) THEN '55'||${clean} ELSE ${clean} END)`}
async function client(db,number){number=phone(number);if(!number)return {match:null,conflict:false};const rows=await db.all(`SELECT * FROM clients WHERE ${expression('phone')}=? OR ${expression('whatsapp')}=? ORDER BY id LIMIT 2`,[number,number]);return {match:rows.length===1?rows[0]:null,conflict:rows.length>1}}
async function contact(db,external,number){number=phone(number);const identity=jid(external),raw=String(external||'');const exact=await db.get("SELECT * FROM chat_contacts WHERE channel='WHATSAPP' AND (external_id=? OR external_id=?) ORDER BY id LIMIT 1",[raw,identity]);if(exact)return exact;if(!number)return null;return db.get(`SELECT * FROM chat_contacts WHERE channel='WHATSAPP' AND (${expression('phone')}=? OR external_id=? OR external_id=?) ORDER BY id LIMIT 1`,[number,number+'@s.whatsapp.net',number+'@c.us'])}
async function serialized(db,fn){const previous=queues.get(db)||Promise.resolve();const work=previous.catch(()=>{}).then(fn);queues.set(db,work);try{return await work}finally{if(queues.get(db)===work)queues.delete(db)}}
async function noteConflict(db,contactId,number){await db.exec("CREATE TABLE IF NOT EXISTS chat_identity_conflicts(contact_id INTEGER NOT NULL REFERENCES chat_contacts(id) ON DELETE CASCADE,reported_phone TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,resolved_at TEXT,resolved_by INTEGER,PRIMARY KEY(contact_id,reported_phone))");await db.run('INSERT INTO chat_identity_conflicts(contact_id,reported_phone) VALUES(?,?) ON CONFLICT(contact_id,reported_phone) DO UPDATE SET resolved_at=NULL,resolved_by=NULL',[contactId,number])}
async function needsReview(db,contactId){if(!await db.get("SELECT name FROM sqlite_master WHERE type='table' AND name='chat_identity_conflicts'"))return false;return !!await db.get('SELECT contact_id FROM chat_identity_conflicts WHERE contact_id=? AND resolved_at IS NULL LIMIT 1',[contactId])}
async function resolveReview(db,contactId,userId){if(await needsReview(db,contactId))await db.run('UPDATE chat_identity_conflicts SET resolved_at=CURRENT_TIMESTAMP,resolved_by=? WHERE contact_id=? AND resolved_at IS NULL',[userId,contactId])}
module.exports={phone,storedPhone,direct,jid,expression,client,contact,serialized,noteConflict,needsReview,resolveReview};
